{"sql": "SET sqlite_all_varchar=true; 
SELECT DISTINCT CAST(strftime('%Y', CAST(QuotaDate AS TIMESTAMP)) AS INTEGER) as Year
FROM SalesPersonQuotaHistory
ORDER BY Year"}

{"sql": "SET sqlite_all_varchar=true; 
SELECT DISTINCT CAST(strftime('%Y', CAST(orderdate AS TIMESTAMP)) AS INTEGER) as Year
FROM salesorderheader
WHERE salespersonid IS NOT NULL AND salespersonid != ''
ORDER BY Year"}

{"sql": "SET sqlite_all_varchar=true; 
SELECT BusinessEntityID, 
       CAST(strftime('%Y', CAST(QuotaDate AS TIMESTAMP)) AS INTEGER) as Year
FROM SalesPersonQuotaHistory
GROUP BY BusinessEntityID, CAST(strftime('%Y', CAST(QuotaDate AS TIMESTAMP)) AS INTEGER)
ORDER BY BusinessEntityID, Year"}

{"sql": "SET sqlite_all_varchar=true; 
SELECT BusinessEntityID, COUNT(*) as cnt
FROM SalesPersonQuotaHistory
GROUP BY BusinessEntityID
ORDER BY cnt"}
